const cases=[{name:'Aurora Pavilion',type:'EXPERIENCE',year:'2026',cover:'hero_arch',desc:'Een sculpturale ontmoetingsplek waar architectuur en licht samenkomen.'},{name:'Lumen Experience',type:'CULTURE',year:'2026',cover:'work_color',desc:'Een immersief universum van kleur, licht en beweging.'},{name:'Echo Spaces',type:'DESIGN',year:'2025',cover:'work_arch',desc:'Een nieuwe kijk op de ruimte tussen mens en omgeving.'},{name:'Pulse Festival',type:'EVENT',year:'2026',cover:'event_lights',desc:'Drie dagen waarin cultuur en technologie samenkomen.'},{name:'Future Assembly',type:'TECHNOLOGY',year:'2026',cover:'journal_event',desc:'Een ideeënfestival voor een verbonden generatie.'},{name:'The Atrium',type:'SPACE',year:'2025',cover:'space_atrium',desc:'Een lichte, open ruimte waar alles mogelijk wordt.'}];
