const people=[{name:'Maya Chen',role:'Creative director',cover:'comm_face'},{name:'Noah Vermeer',role:'Head of experiences',cover:'comm_man'},{name:'Amara Brooks',role:'Design strategist',cover:'journal_face'},{name:'Luca Moreno',role:'Community curator',cover:'comm_person'}];
let currentPath='/',currentBlock='Header (hero)',currentGroup='Alle categorieën',currentBackground='Licht',currentVariant='Standaard',menuOpened=false,showOutlines=false,workFilter='ALL';
function asset(key){return window.NOVA_ASSETS&&NOVA_ASSETS[key]||''}
function photo(key,alt='',extra=''){return `<img src="${asset(key)}" alt="${alt||'Conceptbeeld in de NOVA demonstratiewebsite'}" ${extra}>`}
function link(url){location.hash='/'+url.replace(/^\//,'')}
function picCard(item,large=false){return `<a href="#/work/${item.name.toLowerCase().replaceAll(' ','-')}" class="tagged-card"><div class="image-frame ${large?'tall':''}">${photo(item.cover,item.name)}<div class="image-overlay"></div><div class="image-caption"><div><span class="meta">${item.type} · ${item.year}</span><h3>${item.name}</h3></div><span class="circle-arrow">↗</span></div></div></a>`}
function storyCard(post){return `<a href="#/journal/${post.title.toLowerCase().replaceAll(' ','-')}" class="article-card"><div class="image-frame">${photo(post.cover,post.title)}</div><div class="meta">${post.cat} &nbsp;·&nbsp; ${post.time}</div><h3>${post.title}</h3><p>Perspectieven, verhalen en ideeën die ons verder brengen. <span style="white-space:nowrap">Lees verder ↗</span></p></a>`}
function btn(href,text,cl='btn-lime'){return `<a class="btn ${cl}" href="#/${href}">${text}<span class="arrow">↗</span></a>`}
function sectionLabel(num,text){return `<span class="eyebrow"><span class="label-index">${num} / </span> ${text}</span>`}
function sectionTitle(num,eyebrow,title,desc=''){return `<div class="section-head"><div>${sectionLabel(num,eyebrow)}<h2>${title}</h2></div>${desc?`<p>${desc}</p>`:''}</div>`}
function callout(){return `<section data-cms="Afsluitende oproep · gedeeld" class="footer-cta"><div class="container"><span class="eyebrow" style="color:var(--lime)">WHAT'S NEXT?</span><h2>Have something extraordinary in mind?</h2>${btn('contact','Start een gesprek')}</div></section>`}
function footer(){return `${callout()}<footer class="footer"><div class="container"><div class="footer-top"><a class="brand" href="#/">NOVA<span>.</span></a><div class="footer-links"><div><span class="eyebrow">Explore</span><a href="#/work">Work</a><a href="#/journal">Journal</a><a href="#/experiences">Experiences</a><a href="#/spaces">Spaces</a></div><div><span class="eyebrow">Connect</span><a href="#/community">Community</a><a href="#/about">About</a><a href="#/contact">Contact</a><a href="#/playground">Block Playground</a></div></div></div><div class="footer-one-promo"><div><strong>Gemaakt om te inspireren. Ontworpen voor Link & Lead One.</strong><span>Ontdek de technologie en CMS-blokken achter deze fictieve website.</span></div><a href="#/one" class="btn btn-mini btn-lime">Ontdek het CMS ↗</a></div><div class="footer-end"><span>© NOVA 2026 — Fictief merk voor de CMS-ontwerpdemonstratie.</span><span>Visual design concept by Link & Lead One · Geen live website</span></div></div></footer>`}
function home(){return `<div class="page"><section data-cms="Header (hero) · Diepst" class="hero-home"><div class="hero-visual">${photo('hero_arch','Sculpturale blauwe architectuur met warm oranje licht')}</div><div class="container hero-copy"><div class="eyebrow" style="color:var(--lime)">WELCOME TO CREATIVE FUTURES</div><h1>Ideas deserve<br>to become<br>reality<span style="color:var(--lime)">.</span></h1><p>Een plek voor nieuwe ideeën, inspirerende mensen en bijzondere ervaringen.</p><div class="hero-actions">${btn('work','Explore NOVA')}<a href="#/one" class="btn btn-outline">◉ &nbsp; Ontdek het CMS</a></div></div><div class="hero-bottom"><div class="container"><div class="hero-stats"><div><b>18</b><small>Paginatypes</small></div><div><b>43</b><small>CMS-blokken</small></div><div><b>05</b><small>Kleurenschema's</small></div></div><span class="scroll">SCROLL TO EXPLORE &nbsp; ↓</span></div></div></section><div data-cms="Bewegende tekstband" class="marquee"><div class="container"><span>CREATE &nbsp; / &nbsp; CONNECT &nbsp; / &nbsp; EXPLORE &nbsp; / &nbsp; BUILD &nbsp; / &nbsp;</span></div></div><section data-cms="Tekst met beeld · Licht" class="section"><div class="container intro-grid"><div>${sectionLabel('01','OUR WORLD')}<h2>Where ideas find their people.</h2><p>Wij geloven in de kracht van ontmoetingen. In ruimtes die uitdagen, verhalen die blijven hangen en ideeën die de wereld verder brengen.</p>${btn('about','Ontdek ons verhaal','btn-dark')}</div><div class="image-frame intro-image">${photo('work_color','Kleurrijke lichtinstallatie')}<span class="image-tag">CREATIVITY IN MOTION</span></div></div></section><section data-cms="Cases · collectie" class="section section-soft"><div class="container">${sectionTitle('02','SELECTED WORK','Made to move people.','Van architectuur en ervaringen tot digitale ideeën. Werk dat niet alleen mooi is, maar ook iets losmaakt.')}<div class="portfolio-grid">${picCard(cases[1],true)}${picCard(cases[0])}${picCard(cases[3])}</div><div style="margin-top:33px">${btn('work','Bekijk alle projecten','btn-dark')}</div></div></section><section data-cms="Statement · Donker" class="section section-dark statement"><div class="ring"></div><div class="container">${sectionLabel('03','OUR BELIEF')}<h2>Tomorrow is not something we wait for. <em>It's something we make.</em></h2>${btn('community','Meet our community')}</div></section><section data-cms="Statistieken · Zacht" class="section section-soft"><div class="container">${sectionTitle('04','THE IDEA IN NUMBERS','A world of possibilities.','Fictieve voorbeeldcijfers voor de demonstratie van het CMS-statistiekenblok.')}<div class="stats-grid"><div class="stat"><strong>120<span style="color:#8fa616">+</span></strong><p>Ideas brought to life</p></div><div class="stat"><strong>38</strong><p>Creative collaborators</p></div><div class="stat"><strong>12k</strong><p>Inspired minds</p></div></div></div></section><section data-cms="Team · collectie" class="section"><div class="container">${sectionTitle('05','PEOPLE','Meet the minds.','Ideeën worden pas bijzonder door de mensen die ze vormgeven.')}<div class="people-grid">${people.map(p=>`<div class="person-card"><div class="image-frame">${photo(p.cover,p.name)}</div><h3>${p.name}</h3><p>${p.role}</p></div>`).join('')}</div><div style="margin-top:32px">${btn('community','Ontmoet onze community','btn-dark')}</div></div></section><section data-cms="Artikelen · collectie" class="section section-soft"><div class="container">${sectionTitle('06','THE JOURNAL','Fresh perspectives.','Verhalen om bij stil te staan. En om daarna weer vooruit te kijken.')}<div class="article-grid">${posts.slice(0,3).map(storyCard).join('')}</div><div style="margin-top:34px">${btn('journal','Bekijk alle verhalen','btn-dark')}</div></div></section>${footer()}</div>`}
function work(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero"><div class="container"><span class="eyebrow">OUR WORK / CURATED PROJECTS</span><h1>Projects that<br>make an impact.</h1><div class="hero-description"><span class="meta">DESIGN / CULTURE / EXPERIENCE</span><p>Van immersieve experiences tot digitale platformen. Ontdek hoe ideeën veranderen in betekenisvolle projecten.</p></div></div></section><section data-cms="Cases · collectie en filters" class="section" style="padding-top:0"><div class="container"><div class="chip-row" id="work-filters">${['ALL','EXPERIENCE','DESIGN','CULTURE','EVENT','TECHNOLOGY','SPACE'].map(t=>`<button class="chip ${t===workFilter?'active':''}" onclick="filterWork('${t}')">${t==='ALL'?'Alle projecten':t.toLowerCase()}</button>`).join('')}</div><div class="project-grid" id="projects">${cases.filter(x=>workFilter==='ALL'||x.type===workFilter).map((x)=>`<div>${picCard(x)}<div class="project-title"><div><h3>${x.name}</h3><p>${x.type} · ${x.year}</p></div><span class="arrow">↗</span></div></div>`).join('')}</div></div></section><section data-cms="Bewijsstrook" class="section section-soft"><div class="container">${sectionTitle('02','OUR APPROACH','Every project starts with a question.')}<div class="card-3"><div class="info-tile"><span class="eyebrow">01 / Discover</span><strong>Listen first.</strong><p>Begrijp het probleem en de mensen erachter.</p></div><div class="info-tile"><span class="eyebrow">02 / Create</span><strong>Think bigger.</strong><p>Geef verbeelding en experiment de ruimte.</p></div><div class="info-tile"><span class="eyebrow">03 / Impact</span><strong>Make it matter.</strong><p>Werk aan iets wat mensen raakt.</p></div></div></div></section>${footer()}</div>`}
function journal(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero"><div class="container"><span class="eyebrow">THE JOURNAL / IDEAS & INSIGHTS</span><h1>Stories, ideas<br>and insights.</h1><div class="hero-description"><span class="meta">THINK / QUESTION / IMAGINE</span><p>Verdiepende verhalen, interviews en nieuws over creativiteit, technologie en de toekomst.</p></div></div></section><section data-cms="Artikelen · uitgelicht" class="section" style="padding-top:0"><div class="container"><a href="#/journal/de-kracht-van-immersive-experiences" class="featured-story"><div class="photo">${photo('journal_face','Creatief portret in oranje en blauw')}</div><div class="copy"><span class="eyebrow">FEATURED STORY / CULTURE</span><div><h2>De kracht van immersive experiences.</h2><p style="margin-top:20px">Hoe beleving merken, mensen en plekken dichter bij elkaar brengt.</p></div><span class="meta">LEES HET ARTIKEL &nbsp; ↗</span></div></a></div></section><section data-cms="Artikelen · collectie" class="section section-soft"><div class="container">${sectionTitle('01','MORE TO EXPLORE','Ideas worth sharing.')}<div class="chip-row" style="margin-bottom:25px"><span class="chip active">Alles</span><span class="chip">Design</span><span class="chip">Culture</span><span class="chip">Experiences</span><span class="chip">Future</span></div><div class="article-grid">${posts.slice(1).map(storyCard).join('')}</div></div></section><section data-cms="Formulier · nieuwsbrief" class="section section-lime"><div class="container" style="display:flex;justify-content:space-between;gap:30px;align-items:end;flex-wrap:wrap"><div><span class="eyebrow">NOVA NOTES</span><h2 style="font-size:clamp(55px,7vw,108px);line-height:.96;max-width:720px">A little more inspiration in your inbox.</h2></div><form onsubmit="event.preventDefault();document.getElementById('news-state').innerText='Bedankt! Dit is een visuele demo.'"><div class="form-field"><label for="newsletter">E-mailadres</label><input type="email" id="newsletter" placeholder="jij@voorbeeld.nl" required style="min-width:250px"></div><button class="btn btn-dark" style="margin-top:10px">Aanmelden ↗</button><div id="news-state" style="font-size:12px;margin-top:10px"></div></form></div></section>${footer()}</div>`}
function experiences(){return `<div class="page"><section data-cms="Header (hero) · Diepst" class="feature-media">${photo('event_lights','Publiek bij een creatieve lichtshow')}<div class="container copy"><span class="eyebrow" style="color:var(--lime)">UPCOMING EXPERIENCES</span><h1>Pulse<br>Festival.</h1><p>Een driedaags festival over creativiteit, technologie en de mens van morgen.</p><div class="hero-actions">${btn('experiences/nova-sessions','Bekijk het programma')}<a class="btn btn-outline" href="#/experiences/nova-sessions">Ontdek het event ↗</a></div></div></section><section data-cms="Kaartenrij" class="section"><div class="container">${sectionTitle('01','WHAT TO EXPECT','More than an event.')}<div class="card-3"><div class="info-tile"><span class="eyebrow">01</span><strong>Inspiring speakers.</strong><p>Nieuwe perspectieven van makers en denkers.</p></div><div class="info-tile"><span class="eyebrow">02</span><strong>Immersive art.</strong><p>Ervaar de toekomst met al je zintuigen.</p></div><div class="info-tile"><span class="eyebrow">03</span><strong>Real connections.</strong><p>Ontmoet mensen die iets in beweging brengen.</p></div></div></div></section><section data-cms="Reeks stappen · programma" class="section section-soft"><div class="container">${sectionTitle('02','THE PROGRAM','An experience to remember.','Drie inspirerende dagen. Hier tonen we de visuele uitwerking van een programma en tijdlijn.')}<div class="schedule"><div><div class="schedule-row"><strong>10:00</strong><span>Opening Pulse Festival</span><span>↗</span></div><div class="schedule-row"><strong>11:15</strong><span>Designing tomorrow</span><span>↗</span></div><div class="schedule-row"><strong>13:30</strong><span>Experiences beyond screens</span><span>↗</span></div><div class="schedule-row"><strong>16:00</strong><span>Meet the makers</span><span>↗</span></div></div><div class="image-frame" style="height:360px">${photo('event_gradient','Lichtkunst en festivalatmosfeer')}</div></div></div></section><section data-cms="Sprekers · collectie" class="section"><div class="container">${sectionTitle('03','ON STAGE','Fresh voices. Big ideas.')}<div class="people-grid">${people.map(p=>`<div class="person-card"><div class="image-frame">${photo(p.cover,p.name)}</div><h3>${p.name}</h3><p>Speaker · ${p.role}</p></div>`).join('')}</div></div></section><section data-cms="Prijskaarten / tickets" class="section section-dark"><div class="container">${sectionTitle('04','JOIN THE EXPERIENCE','Find your ticket.')}<div class="tickets">${[['Day Pass','€ 49','Toegang voor één inspirerende festivaldag.'],['Full Experience','€ 119','Alle dagen, alle sessies en alle inspiratie.'],['Community Pass','€ 179','Met extra netwerkervaring en besloten programma.']].map((t,i)=>`<div class="ticket ${i===1?'featured':''}"><div><span class="eyebrow">${i===1?'MOST POPULAR':'ACCESS'}</span><h3 style="margin-top:13px">${t[0]}</h3><p style="margin-top:12px">${t[2]}</p></div><div><strong>${t[1]}</strong><button onclick="alert('Dit is een visueel ontwerp. Er vindt geen betaling plaats.')" class="btn btn-dark" style="display:flex;margin-top:15px">Bekijk tickets ↗</button></div></div>`).join('')}</div><p style="font-size:12px;margin-top:20px;color:#cbd2e0">Fictieve ticketprijzen uitsluitend voor het ontwerp.</p></div></section>${footer()}</div>`}
function spaces(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero"><div class="container"><span class="eyebrow">OUR SPACES / MEET DIFFERENTLY</span><h1>Extraordinary<br>spaces for<br>big ideas.</h1><div class="hero-description"><span class="meta">SPACES THAT INSPIRE</span><p>Flexibele, inspirerende locaties voor evenementen, producties, workshops en meetings.</p></div></div></section><section data-cms="Collectie (lijst) · ruimtes" class="section" style="padding-top:0"><div class="container"><a class="space-card" href="#/spaces/studio-one"><div class="photo">${photo('space_atrium','Licht atrium met planten en modern interieur')}</div><div class="copy"><span class="eyebrow">01 / OUR SPACES</span><h3>The Atrium.</h3><p>Open, licht en vol mogelijkheden. Een ruimte die uitnodigt tot nieuwe perspectieven.</p>${btn('spaces/studio-one','Ontdek deze ruimte','btn-dark')}</div></a><a class="space-card" href="#/spaces/studio-one"><div class="photo">${photo('work_arch','Architectonisch paviljoen')}</div><div class="copy"><span class="eyebrow">02 / OUR SPACES</span><h3>Studio One.</h3><p>Een veelzijdige studio voor workshops, creatieve sessies en presentaties.</p>${btn('spaces/studio-one','Bekijk de studio','btn-dark')}</div></a><a class="space-card" href="#/spaces/studio-one"><div class="photo">${photo('work_color','Kleurrijke ruimtelijke installatie')}</div><div class="copy"><span class="eyebrow">03 / OUR SPACES</span><h3>Light Lab.</h3><p>Een onverwachte omgeving voor eigenzinnige meetings en ervaringen.</p>${btn('spaces/studio-one','Bekijk de ruimte','btn-dark')}</div></a></div></section><section data-cms="Feiten" class="section section-soft"><div class="container">${sectionTitle('02','SPACE FACTS','Your next idea starts here.')}<div class="stats-grid"><div class="stat"><strong>03</strong><p>Unieke ruimtes</p></div><div class="stat"><strong>10–500</strong><p>Personen per opstelling</p></div><div class="stat"><strong>∞</strong><p>Mogelijkheden om te creëren</p></div></div></div></section>${footer()}</div>`}
function community(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero"><div class="container"><span class="eyebrow">OUR COMMUNITY / MADE TOGETHER</span><h1>People make<br>the future.</h1><div class="hero-description"><span class="meta">PEOPLE / CREATIVITY / CONNECTION</span><p>Een groeiende community van creatieven, innovators en organisaties die samen werken aan betekenisvolle projecten.</p></div></div></section><section data-cms="Team en Partners/sponsoren" class="section" style="padding-top:0"><div class="container"><div class="community-mosaic"><div class="image-frame">${photo('comm_face','Portret van een creatieve maker')}<div class="image-overlay"></div><div class="image-caption"><h3>Makers</h3><span class="circle-arrow">↗</span></div></div><div class="image-frame">${photo('comm_man','Creatieve partner')}<div class="image-overlay"></div><div class="image-caption"><h3>Partners</h3></div></div><div class="image-frame">${photo('comm_person','Portret teamlid')}<div class="image-overlay"></div><div class="image-caption"><h3>Team</h3></div></div><div class="image-frame">${photo('comm_event','Community event')}<div class="image-overlay"></div><div class="image-caption"><h3>Moments we share</h3></div></div></div></div></section><section data-cms="Partner uitgelicht" class="section section-soft"><div class="container">${sectionTitle('01','BETTER TOGETHER','Ideas are made to be shared.')}<div class="detail-split"><p class="pullquote">Great things happen when different worlds meet.</p><div class="body-copy"><p>Bij NOVA komen denkers, makers, bedrijven en nieuwsgierige mensen samen. Niet omdat we hetzelfde zijn, maar juist omdat we anders denken.</p>${btn('members','Ontdek de ledenomgeving','btn-dark')}</div></div></div></section><section data-cms="Reviews / Citaten-carrousel" class="section"><div class="container">${sectionTitle('02','WHAT PEOPLE SAY','Real connection. Lasting impact.')}<div class="card-3"><div class="info-tile"><span class="eyebrow">COMMUNITY VOICE</span><strong style="font-size:23px">“Er ontstaat hier ruimte voor ideeën die nergens anders passen.”</strong><p>— Maya Chen · fictieve testimonial</p></div><div class="info-tile"><span class="eyebrow">COMMUNITY VOICE</span><strong style="font-size:23px">“De energie van samen iets maken is ongeëvenaard.”</strong><p>— Noah Vermeer · fictieve testimonial</p></div><div class="info-tile"><span class="eyebrow">COMMUNITY VOICE</span><strong style="font-size:23px">“Je komt voor een event en vertrekt met een perspectief.”</strong><p>— Amara Brooks · fictieve testimonial</p></div></div></div></section>${footer()}</div>`}
function about(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero"><div class="container"><span class="eyebrow">ABOUT / OUR STORY</span><h1>Make room<br>for what’s next.</h1><div class="hero-description"><span class="meta">DESIGNING NEW POSSIBILITIES</span><p>NOVA is een fictieve creatieve wereld, speciaal ontworpen om te laten zien wat Link & Lead One mogelijk maakt.</p></div><div class="lead-image image-frame">${photo('hero_arch','Abstract architectonisch paviljoen')}</div></div></section><section data-cms="Statement" class="section section-dark statement"><div class="container"><span class="eyebrow" style="color:var(--lime)">OUR MISSION</span><h2>We believe <em>ideas grow</em> when worlds connect.</h2></div></section><section data-cms="Reeks stappen · tijdlijn" class="section"><div class="container">${sectionTitle('01','OUR PROCESS','From spark to impact.')}<div class="timeline"><div class="timeline-item"><strong>01</strong><h3>Discover</h3><p>Luisteren, observeren, doorvragen.</p></div><div class="timeline-item"><strong>02</strong><h3>Imagine</h3><p>Nieuwe mogelijkheden durven zien.</p></div><div class="timeline-item"><strong>03</strong><h3>Create</h3><p>Ideeën tastbaar maken.</p></div><div class="timeline-item"><strong>04</strong><h3>Connect</h3><p>Mensen en plannen samenbrengen.</p></div></div></div></section><section data-cms="Team" class="section section-soft"><div class="container">${sectionTitle('02','OUR PEOPLE','Meet the makers.')}<div class="people-grid">${people.map(p=>`<div class="person-card"><div class="image-frame">${photo(p.cover,p.name)}</div><h3>${p.name}</h3><p>${p.role}</p></div>`).join('')}</div></div></section>${footer()}</div>`}
function contact(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero"><div class="container"><span class="eyebrow">CONTACT / GET IN TOUCH</span><h1>Let's make<br>something happen.</h1><div class="hero-description"><span class="meta">SAY HELLO</span><p>Een vraag, een idee of gewoon nieuwsgierig? Laat van je horen.</p></div></div></section><section data-cms="Formulier / Kaart en locatie" class="section" style="padding-top:25px"><div class="container contact-layout"><div><span class="eyebrow">TELL US ABOUT YOUR IDEA</span><h2>What's on your mind?</h2><p class="side-note">We zijn benieuwd naar je plannen. Dit formulier is een visueel ontwerp en verzendt nog geen berichten.</p><div style="margin-top:70px"><span class="eyebrow">FICTIONAL HEADQUARTERS</span><p style="font-size:18px;margin-top:12px">NOVA Creative Campus<br>Demolocatie · geen bezoekadres</p></div></div><div><form class="form-grid" onsubmit="event.preventDefault();document.getElementById('contact-state').innerText='Bedankt! Dit is een visuele demo; er is niets verstuurd.'"><div class="form-field"><label for="first-name">Voornaam *</label><input id="first-name" required placeholder="Je voornaam" /></div><div class="form-field"><label for="email">E-mailadres *</label><input id="email" type="email" required placeholder="jij@voorbeeld.nl" /></div><div class="form-field full"><label for="interest">Waar gaat je idee over?</label><select id="interest"><option>Een creatief project</option><option>Een evenement</option><option>Een ruimte huren</option><option>Een samenwerking</option></select></div><div class="form-field full"><label for="message">Vertel ons meer *</label><textarea id="message" placeholder="Wat kunnen we samen maken?" required></textarea></div><div class="form-field full"><button class="btn btn-dark" style="width:fit-content">Verstuur je bericht ↗</button><div id="contact-state" style="font-size:12px;margin-top:9px"></div></div></form><p class="demo-note" style="margin-top:25px">Deze formulierstaten zijn uitsluitend voor visuele beoordeling. In de werkende website worden ze gekoppeld aan de bestaande CMS-formuliermodule.</p></div></div></section>${footer()}</div>`}
function lab(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero night"><div class="container"><span class="eyebrow" style="color:var(--lime)">NOVA LAB / PLAY WITH IDEAS</span><h1>Explore.<br>Experiment.<br>Experience.</h1><div class="hero-description"><span class="meta">THE INTERACTIVE LAB</span><p>De ruimte voor configuratoren, enquêtes, personalisatie, testen en slimme formulieren.</p></div></div></section><section data-cms="Configurator" class="section"><div class="container">${sectionTitle('01','THE EXPERIENCE BUILDER','Shape your own experience.','Kies een opzet en ontdek hoe een prijsconfigurator eruit kan zien. Alle bedragen zijn fictief.')}<div class="detail-split"><div class="image-frame" style="height:470px">${photo('space_atrium','Studio voor evenementen')}</div><div style="display:grid;align-content:start;gap:20px"><div class="form-field"><label for="lab-pkg">Type ervaring</label><select id="lab-pkg" onchange="calcPrice()"><option value="150">Creative Session — € 150</option><option value="300">Immersive Event — € 300</option><option value="450">Full Experience — € 450</option></select></div><div class="form-field"><label for="lab-people">Aantal deelnemers</label><input type="range" min="5" max="100" value="25" id="lab-people" oninput="calcPrice()" /><div style="font-size:13px"><strong id="people-val">25</strong> personen</div></div><div style="background:var(--mist);padding:30px"><span class="eyebrow">INDICATIEVE DEMOPRIJS</span><h3 style="font-size:70px" id="lab-price">€ 650</h3><p style="font-size:12px">Demonstratie zonder offerte of betaalverplichting.</p></div>${btn('contact','Vraag meer informatie','btn-dark')}</div></div></div></section><section data-cms="Enquête / NPS · A/B-test · Personalisatie" class="section section-soft"><div class="container">${sectionTitle('02','SMART INTERACTIONS','See what else is possible.')}<div class="showcase-table"><div class="showcase-tile"><div><span class="eyebrow">ENQUÊTE / NPS</span><h3 style="margin-top:12px">How was your experience?</h3></div><div><div class="chip-row">${[7,8,9,10].map(x=>`<button class="chip" onclick="this.parentNode.querySelectorAll('.chip').forEach(n=>n.classList.remove('active'));this.classList.add('active')">${x}</button>`).join('')}</div><p style="margin-top:12px">Selecteer een demoscore.</p></div></div><div class="showcase-tile"><div><span class="eyebrow">A/B-TEST</span><h3 style="margin-top:12px" id="ab-text">Create what's next.</h3></div><button class="btn btn-dark" onclick="document.getElementById('ab-text').innerText=document.getElementById('ab-text').innerText==='Create what\'s next.'?'Make tomorrow happen.':'Create what\'s next.'">Wissel tekstvariant ↗</button></div><div class="showcase-tile"><div><span class="eyebrow">PERSONALISATIE</span><h3 style="margin-top:12px" id="person-text">Welkom bij NOVA.</h3></div><button class="btn btn-dark" onclick="document.getElementById('person-text').innerText=document.getElementById('person-text').innerText==='Welkom bij NOVA.'?'Goed je weer te zien!':'Welkom bij NOVA.'">Simuleer vaste bezoeker ↗</button></div></div></div></section>${footer()}</div>`}
function members(){return `<div class="page"><section data-cms="Header (hero)" class="inner-hero night"><div class="container"><span class="eyebrow" style="color:var(--lime)">MEMBERS / YOUR SPACE</span><h1>A place for<br>our people.</h1><p style="max-width:490px;color:#c0c7d8">Een besloten omgeving waar leden exclusieve ideeën, sessies en projecten ontdekken.</p></div></section><section data-cms="Ledentoegang" class="section"><div class="container" style="max-width:640px"><span class="eyebrow">MEMBER ACCESS</span><h2 style="font-size:68px;margin:18px 0">Welcome back.</h2><form class="form-grid" onsubmit="event.preventDefault();document.getElementById('member-state').innerText='Dit is een voorbeeldscherm. Er is geen echte login.'"><div class="form-field full"><label for="member-email">E-mailadres</label><input id="member-email" type="email" placeholder="jij@voorbeeld.nl" required></div><div class="form-field full"><label for="member-pass">Wachtwoord</label><input id="member-pass" type="password" placeholder="••••••••" required></div><button class="btn btn-dark" style="width:fit-content">Inloggen ↗</button></form><p id="member-state" style="margin-top:18px"></p><p class="demo-note" style="margin-top:22px">Visueel loginconcept, geen echte autorisatie of opslag.</p></div></section>${footer()}</div>`}
function playground(){const groups=['Alle categorieën',...Object.keys(cmsGroups)];const blocks=currentGroup==='Alle categorieën'?Object.values(cmsGroups).flat():cmsGroups[currentGroup];if(!blocks.includes(currentBlock))currentBlock=blocks[0];let bgcolor=({'Licht':'light','Zacht':'soft','Accent':'accent','Donker':'dark','Diepst':'deepest'})[currentBackground];return `<div class="page"><section class="inner-hero" style="padding-bottom:65px"><div class="container"><span class="eyebrow">LINK & LEAD ONE / BLOCK EXPLORER</span><h1>One system.<br>43 possibilities.</h1><div class="hero-description"><span class="meta">43 GENERIC CONTENT BLOCKS</span><p>De visuele bibliotheek van alle generieke CMS-blokken. Dit is een ontwerpvoorstel, nog geen live weergave van de echte componenten.</p></div></div></section><section class="section section-soft" style="padding-top:50px"><div class="container"><div class="chip-row" style="margin-bottom:28px">${groups.map(g=>`<button class="chip ${g===currentGroup?'active':''}" onclick="selectGroup('${g}')">${g}</button>`).join('')}</div><div class="playground-layout"><aside class="block-menu"><span class="eyebrow">BLOCK LIBRARY · ${blocks.length} BLOKKEN</span><h3>Select a block.</h3><div class="block-list">${blocks.map((b,i)=>`<button class="${b===currentBlock?'active':''}" onclick="selectBlock(${JSON.stringify(b).replaceAll('"','&quot;')})"><span>${b}</span><span>↗</span></button>`).join('')}</div></aside><div class="block-viewer"><div class="toolbar"><div><span class="eyebrow">LIVE DESIGN PREVIEW</span><h3 style="font-size:29px;margin-top:6px">${currentBlock}</h3></div><div style="display:flex;gap:7px;flex-wrap:wrap"><select aria-label="Kies achtergrond" onchange="setBackground(this.value)">${['Licht','Zacht','Accent','Donker','Diepst'].map(s=>`<option ${s===currentBackground?'selected':''}>${s}</option>`).join('')}</select><select aria-label="Kies variant" onchange="setVariant(this.value)">${['Standaard','Compact','Uitgebreid'].map(s=>`<option ${s===currentVariant?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="block-preview ${bgcolor}"><span class="eyebrow" style="position:relative;z-index:1">${currentGroup==='Alle categorieën'?'NOVA BLOCK SHOWCASE':currentGroup.toUpperCase()}</span><h3 style="position:relative;z-index:1">${previewHeadline(currentBlock)}</h3><p style="position:relative;z-index:1">${previewDescription(currentBlock)}</p><div style="position:relative;z-index:1;margin-top:25px"><span class="btn btn-lime">Discover more ↗</span></div><div class="preview-art">${photo('work_color','Abstracte ontwerpvisual')}</div></div><div class="block-details"><div><strong>CMS-blok</strong><br><span>${currentBlock}</span></div><div><strong>Ontwerpachtergrond</strong><br><span>${currentBackground}</span></div><div><strong>Previewvariant</strong><br><span>${currentVariant}</span></div></div><div class="demo-note" style="margin-top:14px">De 43 namen komen uit de CMS-specificatie. De preview is een visuele indicatie; de precieze velden en varianten worden in de bouwfase gekoppeld aan de bestaande CMS-implementatie.</div></div></div></div></section>${footer()}</div>`}
function previewHeadline(b){if(/Formulier|Enquête|NPS|Review/.test(b))return 'Let’s stay connected.';if(/Artikel|Cases|Portfolio|Collectie/.test(b))return 'Stories worth sharing.';if(/Team|Partner|Sprekers|Testimonial/.test(b))return 'Made possible by people.';if(/Statist|Feiten|Bewijs/.test(b))return 'Ideas with an impact.';if(/Tickets|Prijs|Configurat/.test(b))return 'Your experience, your way.';if(/Agenda|Aftel|Wedstrijd/.test(b))return 'The moments that move us.';return 'Create what’s next.'}
function previewDescription(b){return `Een visueel voorbeeld van het blok “${b}”, binnen de NOVA-huisstijl. Wissel hierboven tussen achtergronden en weergaven.`}

function one(){return `<div class="page">
<section class="one-hero" data-cms="Productpromotie / eigen frontendmodule (geen CMS-kernblok)"><div class="container">
<span class="eyebrow" style="color:var(--lime)">LINK & LEAD ONE / HET CMS ACHTER DE ERVARING</span>
<h1>Je zag de website.<br><span style="color:var(--lime)">Ontdek wat erachter zit.</span></h1>
<p class="one-intro">NOVA laat zien hoeveel ontwerpvrijheid je kunt combineren met overzichtelijk contentbeheer. Ontdek de blokken, collecties en mogelijkheden van Link & Lead One in een interactieve demonstratie.</p>
<div class="one-cta-row"><a class="btn btn-lime" href="#/demo">Start de rondleiding <span class="arrow">↗</span></a><a class="btn btn-outline" href="#/playground">Bekijk de 43 blokken <span class="arrow">↗</span></a></div>
<div class="one-proof"><div><strong>43</strong><small>algemene contentblokken</small></div><div><strong>05</strong><small>achtergrondvarianten</small></div><div><strong>01</strong><small>centrale contentervaring</small></div></div>
</div></section>
<section class="section" data-cms="Tekst met beeld"><div class="container one-split"><div>${sectionLabel('01','LIVE DESIGN SHOWCASE')}<h2 style="font-size:clamp(50px,6.5vw,90px);line-height:.96;margin:20px 0 25px">Mooi van buiten. Slim ingericht.</h2><p>Van een krachtige hero tot dynamische artikelen, van testimonials tot een configurator: laat zien hoe een echte website is opgebouwd uit beheersbare onderdelen.</p><div style="margin-top:26px">${btn('','Bekijk NOVA live','btn-dark')}</div></div><div class="one-shot">${photo('hero_arch','NOVA visualisatie: architecturaal lichtobject')}</div></div></section>
<section class="section section-soft" data-cms="Kaartenrij"><div class="container">${sectionTitle('02','WAT JE KUNT LATEN ZIEN','Ontworpen om te ontdekken.','Alle onderstaande onderdelen komen voor in de bijgevoegde CMS-specificatie. Hun volledige integratie moet binnen de bestaande codebase worden bevestigd.')}<div class="one-benefits"><div class="one-benefit"><span class="one-index">01 / REDACTIE</span><h3>Van tekst tot beeld.</h3><p>Beheer paginaonderdelen met vaste velden, media en verschillende lay-outs. Content staat centraal.</p></div><div class="one-benefit"><span class="one-index">02 / CONTENT</span><h3>Collecties die meebewegen.</h3><p>Toon cases, artikelen, teamleden en reviews waar ze relevant zijn, vanuit aparte verzamelingen.</p></div><div class="one-benefit"><span class="one-index">03 / CONVERSIE</span><h3>Meer dan een brochure.</h3><p>Gebruik formulieren, enquêtes, prijskaarten en configurators om bezoekers actief te betrekken.</p></div></div></div></section>
<section class="section one-dark" data-cms="Statement"><div class="container">${sectionLabel('03','THE REAL POWER')}<h2 style="font-size:clamp(55px,8vw,126px);line-height:.98;max-width:1020px;margin:24px 0">Eén systeem.<br><span style="color:var(--lime)">Jouw eigen uitstraling.</span></h2><p style="max-width:650px">Een eigen frontend geeft ontwerpvrijheid. Het CMS zorgt dat redacteuren inhoud, blokken en collecties kunnen beheren. NOVA is het visuele bewijs van die combinatie.</p><div class="one-chip-row"><span class="one-chip">Eigen huisstijl per site</span><span class="one-chip">Blokken & varianten</span><span class="one-chip">Dynamische collecties</span><span class="one-chip">Formulieren & interactie</span><span class="one-chip">Responsive weergave</span></div>${btn('playground','Ontdek de Playground')}</div></section>
<section class="section" data-cms="Reeks stappen"><div class="container">${sectionTitle('04','IN VIJF MINUTEN','Zie het verschil.','Niet alleen over functies praten. Laat de bezoeker zelf ervaren wat er in het CMS kan.')}<div class="steps"><div class="step"><span>01</span> Bekijk de indrukwekkende NOVA-homepage <b>↗</b></div><div class="step"><span>02</span> Markeer het onderliggende CMS-blok <b>↗</b></div><div class="step"><span>03</span> Open de bijbehorende editor (na koppeling) <b>↗</b></div><div class="step"><span>04</span> Ontdek collecties, formulieren en varianten <b>↗</b></div><div class="step"><span>05</span> Bekijk dezelfde website op mobiel <b>↗</b></div></div></div></section>
<section class="section section-soft" data-cms="Flexibel blok"><div class="container">${sectionTitle('05','VOOR WIE','Voor wie het niet standaard mag zijn.')}<div class="one-benefits"><div class="one-benefit"><span class="one-index">TEAMS</span><h3>Marketingteams</h3><p>Maak aantrekkelijke pagina's met consistente bouwstenen en beheersbare content.</p></div><div class="one-benefit"><span class="one-index">BUREAUS</span><h3>Creatieve bureaus</h3><p>Ontwerp bijzondere frontends, terwijl de klant de inhoud overzichtelijk kan beheren.</p></div><div class="one-benefit"><span class="one-index">ORGANISATIES</span><h3>Meerdere merken</h3><p>Gebruik per site een eigen huisstijl. Bevestig multi-sitebeheer en rechten binnen de echte CMS-omgeving.</p></div></div><div class="one-promo-ribbon"><div><strong>Probeer niet te verbeelden wat er mogelijk is. Bekijk het.</strong><p>Start de interactieve demonstratie of open direct de blokkenbibliotheek.</p></div><a href="#/demo" class="btn btn-dark">Open de demo <span class="arrow">↗</span></a></div></div></section>
<section class="one-end" data-cms="Afsluitende oproep / product"><div class="container"><span class="eyebrow">THE WEBSITE IS THE PROOF</span><h2>Great websites deserve a better way to work.</h2><div class="one-cta-row"><a class="btn btn-dark" href="#/demo">Ontdek Link & Lead One <span class="arrow">↗</span></a><a class="btn btn-outline" style="color:var(--night)" href="#/playground">Bekijk alle mogelijkheden <span class="arrow">↗</span></a></div><p class="one-honest">Dit is een visueel prototype. Voor een live saleswebsite moet de echte CMS-koppeling en aanvraagroute nog worden ingesteld.</p></div></section>${footer()}</div>`}

function demo(){return `<div class="page"><section class="inner-hero night"><div class="container"><span class="eyebrow" style="color:var(--lime)">LINK & LEAD ONE / THE SHOWCASE</span><h1>See the design.<br>Discover the CMS.</h1><div class="hero-description"><span class="meta">GUIDED DESIGN EXPERIENCE</span><p>Een presentatieroute door de fictieve NOVA-website. De visuele fase gaat vooraf aan de werkende CMS-koppeling.</p></div></div></section><section class="section"><div class="container"><div class="demo-launch"><div><span class="eyebrow" style="color:var(--lime)">THE FIVE-MINUTE TOUR</span><h2>Show, don't tell.</h2><p>Zo demonstreer je straks de kracht van een prachtig ontworpen website én de flexibiliteit van het CMS erachter.</p><div style="margin-top:25px">${btn('','Start op de homepage')}</div></div><div class="steps"><div class="step"><span>01</span> Open de prachtige homepage <b>↗</b></div><div class="step"><span>02</span> Toon de CMS-bloklabels <b>↗</b></div><div class="step"><span>03</span> Navigeer door projecten en artikelen <b>↗</b></div><div class="step"><span>04</span> Test een configurator en formulier <b>↗</b></div><div class="step"><span>05</span> Bekijk de 43 blokken in de Playground <b>↗</b></div><div class="step"><span>06</span> Wissel naar mobiele weergave <b>↗</b></div></div></div><div class="showcase-table" style="margin-top:25px"><a class="showcase-tile" href="#/work"><span class="eyebrow">EXPLORE</span><h3>Projecten en dynamische collecties</h3><span class="meta">OPEN WORK ↗</span></a><a class="showcase-tile" href="#/lab"><span class="eyebrow">EXPERIMENT</span><h3>Formulieren en interactieve onderdelen</h3><span class="meta">OPEN LAB ↗</span></a><a class="showcase-tile" href="#/playground"><span class="eyebrow">DISCOVER</span><h3>Alle 43 generieke CMS-blokken</h3><span class="meta">OPEN PLAYGROUND ↗</span></a></div></div></section>${footer()}</div>`}
function detail(kind,slug){if(kind==='work'){let item=cases.find(x=>x.name.toLowerCase().replaceAll(' ','-')===slug)||cases[0];return `<div class="page"><section data-cms="Header · projectdetail" class="detail-hero">${photo(item.cover,item.name)}<div class="container copy"><span class="eyebrow" style="color:var(--lime)">SELECTED WORK / ${item.type}</span><h1>${item.name}.</h1><p>${item.desc}</p></div></section><div class="container mini-info"><div><span>SECTOR</span><strong>${item.type}</strong></div><div><span>YEAR</span><strong>${item.year}</strong></div><div><span>CLIENT</span><strong>NOVA Demo Project</strong></div><div><span>SERVICES</span><strong>Concept / Design / Experience</strong></div></div><section data-cms="Tekst met beeld" class="section"><div class="container detail-split"><p class="pullquote">Designed to leave an impression.</p><div class="body-copy"><p>Dit project begon met een simpele vraag: hoe maak je van een plek een ervaring die mensen bijblijft? We creëerden een wereld waar ruimte, licht en verhaal elkaar ontmoeten.</p><p>Van de eerste schets tot de laatste ontmoeting stond de bezoeker centraal. Het resultaat is een ervaring die verwondert en uitnodigt tot ontdekken.</p>${btn('work','Terug naar alle projecten','btn-dark')}</div></div></section><section data-cms="Portfolio / extra beelden" class="section section-soft" style="padding-top:0"><div class="container"><div class="wide-photo">${photo('work_color','Sfeervol projectbeeld')}</div><div class="card-3" style="margin-top:14px"><div class="image-frame" style="height:300px">${photo('hero_arch')}</div><div class="image-frame" style="height:300px">${photo('space_atrium')}</div><div class="image-frame" style="height:300px">${photo('event_lights')}</div></div></div></section>${footer()}</div>`}if(kind==='journal'){const post=posts.find(x=>x.title.toLowerCase().replaceAll(' ','-')===slug)||posts[0];return `<div class="page"><article class="container article-page" data-cms="Header + Tekstblok"><span class="eyebrow">${post.cat} / THE JOURNAL</span><h1>${post.title}.</h1><p class="lead">Waarom nieuwe ideeën, mensen en plekken een steeds belangrijkere rol spelen in de manier waarop we samenkomen en creëren.</p><div class="meta" style="margin-bottom:30px">NOVA EDITORIAL &nbsp; · &nbsp; ${post.time} &nbsp; · &nbsp; VOORBEELDARTIKEL</div><div class="wide-photo">${photo(post.cover,post.title)}</div><div class="article-body"><p>De mooiste ideeën ontstaan vaak op de grens tussen disciplines. Waar architectuur, technologie en cultuur elkaar raken, groeit ruimte voor onverwachte ervaringen.</p><p>Bij NOVA geloven we dat vernieuwen begint met nieuwsgierigheid. Niet met de nieuwste techniek of het grootste podium, maar met de vraag wat we voor mensen mogelijk willen maken.</p><h2>Experience first.</h2><p>Een sterke ervaring vertelt een verhaal zonder alles uit te leggen. Ze maakt bezoekers niet alleen toeschouwer, maar onderdeel van wat er gebeurt. Dat vraagt om ruimte, ritme en een scherp gevoel voor detail.</p><blockquote>Great design makes people feel something.</blockquote><p>Van een intieme studio tot een grootschalig festival: de uitgangspunten blijven hetzelfde. Zoek naar wat verbindt, laat ruimte voor verwondering en maak iets dat betekenis heeft.</p><p>Dit artikel bevat fictieve voorbeeldcontent, speciaal geschreven voor het visuele CMS-ontwerp.</p></div></article><section class="section section-soft"><div class="container">${sectionTitle('NEXT','READ MORE','Stories worth sharing.')}<div class="article-grid">${posts.slice(0,3).map(storyCard).join('')}</div></div></section>${footer()}</div>`}if(kind==='experiences'){return `<div class="page"><section data-cms="Header · eventdetail" class="detail-hero">${photo('event_lights','Creative festival')}<div class="container copy"><span class="eyebrow" style="color:var(--lime)">NOVA SESSIONS / EVENT EXPERIENCE</span><h1>NOVA Sessions.</h1><p>Drie dagen vol verhalen, makers en ideeën die perspectief bieden. Datum en programma zijn fictief.</p></div></section><div class="container mini-info"><div><span>DATUM</span><strong>12–14 september 2027</strong></div><div><span>LOCATIE</span><strong>NOVA Creative Campus (fictief)</strong></div><div><span>DOELGROEP</span><strong>Makers en innovators</strong></div></div><section class="section"><div class="container">${sectionTitle('01','THE PROGRAM','Three days. Infinite ideas.')}<div class="schedule"><div><div class="schedule-row"><strong>10:00</strong><span>Welcome & Creative Futures</span><span>↗</span></div><div class="schedule-row"><strong>11:30</strong><span>Beyond the expected</span><span>↗</span></div><div class="schedule-row"><strong>14:00</strong><span>Meet the makers</span><span>↗</span></div></div><div class="image-frame" style="height:360px">${photo('journal_event')}</div></div></div></section><section class="section section-soft"><div class="container">${sectionTitle('02','YOUR TICKET','Choose your experience.')}<div class="tickets"><div class="ticket"><h3>Day ticket.</h3><strong>€ 49</strong><button class="btn btn-dark" onclick="alert('Visuele demo: er wordt geen ticket verkocht.')">Ticket bekijken ↗</button></div><div class="ticket featured"><h3>Full pass.</h3><strong>€ 119</strong><button class="btn btn-dark" onclick="alert('Visuele demo: er wordt geen ticket verkocht.')">Ticket bekijken ↗</button></div><div class="ticket"><h3>Group pass.</h3><strong>€ 399</strong><button class="btn btn-dark" onclick="alert('Visuele demo: er wordt geen ticket verkocht.')">Ticket bekijken ↗</button></div></div></div></section>${footer()}</div>`}return `<div class="page"><section data-cms="Header · ruimtedetail" class="detail-hero">${photo('space_atrium','Moderne inspirerende ruimte')}<div class="container copy"><span class="eyebrow" style="color:var(--lime)">NOVA SPACES</span><h1>Studio One.</h1><p>Een inspirerende plek voor ideeën, ontmoetingen en nieuwe mogelijkheden.</p></div></section><div class="container mini-info"><div><span>OPPERVLAKTE</span><strong>240 m² (demo)</strong></div><div><span>CAPACITEIT</span><strong>10–150 personen (demo)</strong></div><div><span>FACILITEITEN</span><strong>AV / Wifi / Catering</strong></div></div><section class="section"><div class="container">${sectionTitle('01','THE SPACE','Everything you need to create.')}<div class="intro-grid"><div class="body-copy"><p>Rust, licht en flexibiliteit: Studio One is ontworpen om samen iets bijzonders te maken. Ideaal voor presentaties, workshops en creatieve bijeenkomsten.</p><p>Er zijn meerdere opstellingen mogelijk, afhankelijk van je programma en het aantal deelnemers.</p>${btn('lab','Stel je arrangement samen','btn-dark')}</div><div class="image-frame" style="height:420px">${photo('work_arch')}</div></div></div></section><section data-cms="Configurator / Agenda-inplanner" class="section section-soft"><div class="container">${sectionTitle('02','DESIGN YOUR VISIT','Your event, your way.')}<div class="card-3"><div class="info-tile"><span class="eyebrow">STEP 01</span><strong>Kies je ervaring</strong><p>Workshop, presentatie of evenement.</p></div><div class="info-tile"><span class="eyebrow">STEP 02</span><strong>Bepaal je gezelschap</strong><p>Flexibele opstellingen voor groepen.</p></div><div class="info-tile"><span class="eyebrow">STEP 03</span><strong>Plan je bezoek</strong><p>Vraag naar een geschikte datum.</p></div></div><div style="margin-top:30px">${btn('lab','Open de voorbeeldconfigurator','btn-dark')}</div></div></section>${footer()}</div>`}
function sports(){return `<div class="page"><section class="inner-hero"><div class="container"><span class="eyebrow">BLOCK PLAYGROUND / SPORTS</span><h1>Every team.<br>Every moment.</h1><p>Een aparte visuele omgeving voor de bestaande blokken Wedstrijden en Volgende wedstrijd.</p></div></section><section data-cms="Wedstrijden en Volgende wedstrijd" class="section section-dark"><div class="container">${sectionTitle('01','THE NEXT MATCH','NOVA United.')}<div class="featured-story" style="background:#dff29e;min-height:300px"><div style="padding:60px"><span class="eyebrow">NEXT MATCH / HOME</span><h2 style="font-size:80px;margin-top:15px">NOVA  /  ATLAS</h2><p style="font-size:15px;color:#1b2b3c;margin-top:15px">Fictieve wedstrijd · 24 april 2027 · 16:00</p></div><div style="padding:60px;display:flex;align-items:center;justify-content:center"><div style="font-size:150px;font-weight:950;letter-spacing:-.1em">N<span style="color:#738900">.</span></div></div></div><div class="schedule" style="margin-top:40px"><div><div class="schedule-row"><strong>24 APR</strong><span>NOVA United — Atlas FC</span><span>↗</span></div><div class="schedule-row"><strong>1 MEI</strong><span>Harbor City — NOVA United</span><span>↗</span></div></div><div class="demo-note">Uitsluitend fictieve uitslagen en wedstrijddatums.</div></div></section>${footer()}</div>`}
function error404(){return `<div class="notfound container"><span class="eyebrow">404 / PAGE NOT FOUND</span><h1>Oops.</h1><p>Ook in het visuele ontwerp kan een pagina ontbreken.</p><div style="margin-top:30px">${btn('','Terug naar NOVA','btn-dark')}</div></div>`}
function filterWork(t){workFilter=t;render(false)}function selectGroup(g){currentGroup=g;render(false)}function selectBlock(b){currentBlock=b;render(false)}function setBackground(b){currentBackground=b;render(false)}function setVariant(b){currentVariant=b;render(false)}function calcPrice(){let p=Number(document.getElementById('lab-pkg').value),n=Number(document.getElementById('lab-people').value);document.getElementById('people-val').textContent=n;document.getElementById('lab-price').textContent='€ '+(p+n*20).toLocaleString('nl-NL')}
function toggleMenu(){menuOpened=!menuOpened;document.getElementById('header').classList.toggle('nav-open',menuOpened);document.getElementById('menu-button').textContent=menuOpened?'×':'☰';document.getElementById('mobile').style.display=menuOpened?'block':'none'}function toggleDemo(){document.getElementById('demoPanel').classList.toggle('open')}function toggleOutlines(){showOutlines=!showOutlines;document.body.classList.toggle('demo-active',showOutlines);document.getElementById('cmsSwitch').classList.toggle('on',showOutlines)}function setAccent(s){document.documentElement.style.setProperty('--lime',s)}
function render(scrollTop=true){let path=decodeURIComponent(location.hash.replace(/^#\/?/,''))||'';currentPath='/'+path;let out='';if(path==='')out=home();else if(path==='work')out=work();else if(path==='journal')out=journal();else if(path==='experiences')out=experiences();else if(path==='spaces')out=spaces();else if(path==='community')out=community();else if(path==='about')out=about();else if(path==='contact')out=contact();else if(path==='lab')out=lab();else if(path==='members')out=members();else if(path==='playground')out=playground();else if(path==='playground/sports')out=sports();else if(path==='demo')out=demo();else if(path==='one')out=one();else if(path.startsWith('work/'))out=detail('work',path.slice(5));else if(path.startsWith('journal/'))out=detail('journal',path.slice(8));else if(path.startsWith('experiences/'))out=detail('experiences',path.slice(12));else if(path.startsWith('spaces/'))out=detail('spaces',path.slice(7));else out=error404();document.getElementById('app').innerHTML=out;let darkHeader=['','experiences','members','lab','demo','one'].includes(path)||path.startsWith('work/')||path.startsWith('spaces/')||path.startsWith('experiences/');let h=document.getElementById('header');h.className='site-header '+(darkHeader?'dark':'light');if(menuOpened)toggleMenu();document.getElementById('primary').innerHTML=nav.map(([t,p])=>`<a class="${path===p?'active':''}" href="#/${p}">${t}</a>`).join('');document.getElementById('mobile').innerHTML=[...nav,['Contact','contact'],['The Lab','lab'],['Block Playground','playground'],['Design Demo','demo'],['Het CMS','one']].map(([t,p])=>`<a href="#/${p}" onclick="toggleMenu()">${t} ↗</a>`).join('')+'<p class="mob-note">NOVA · visuele demo voor Link & Lead One</p>';if(scrollTop)window.scrollTo(0,0);onScroll()}
